draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 25, 25, 0, 2 * Math.PI);
  ctx.stroke();

  // dog ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 40);
  ctx.lineTo(W/2 - 25, H/2 - 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 40);
  ctx.lineTo(W/2 + 25, H/2 - 60 + 20 * Math.sin(t));
  ctx.stroke();

  // dog mouth
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 10);
  ctx.lineTo(W/2 + 10, H/2 - 10);
  ctx.stroke();

  // howling effect
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 10, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
